package dev.mttmcknn.seaglass.internal

import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.util.Properties
import javax.imageio.ImageIO
import kotlin.math.abs
import kotlin.math.max
import kotlin.math.sqrt
import kotlin.test.Test
import kotlin.test.assertContentEquals
import kotlin.test.assertEquals
import kotlin.test.assertTrue

/**
 * Independent goldens are generated by the unchanged, approved JavaScript demo.
 * Injecting its antialiased mask isolates shader math from platform rasterizers.
 * Full-image comparisons additionally include the native ground compositing.
 */
class WebReferenceParityTest {
    @Test
    fun randomSequencesMatchJavaScriptIncludingUnsignedSeeds() {
        val properties = properties("random.properties")
        for (seed in listOf(0L, 1L, 42L, 4294967295L)) {
            val random = SeededRandom(seed.toInt())
            for ((index, expected) in properties.numbers("seed.$seed").withIndex()) {
                assertEquals(expected, random.nextDouble(), "seed=$seed output=$index")
            }
        }
    }

    @Test
    fun tumbledContoursAndCubicSegmentsMatchTheWeb() {
        for (fixture in fixtures()) {
            val points = buildContour(fixture.width, fixture.height, fixture.shape, fixture.settings.tumble, fixture.settings.seed)
            assertNumbers(fixture.id + " contour", fixture.properties.numbers("contour"), points.flatMap { listOf(it.x, it.y) }, 1e-9)
            val segments = contourSegments(points)
            val coordinates = segments.flatMap { segment ->
                listOf(segment.start, segment.control1, segment.control2, segment.end).flatMap { listOf(it.x, it.y) }
            }
            assertNumbers(fixture.id + " segments", fixture.properties.numbers("segments"), coordinates, 1e-9)
        }
    }

    @Test
    fun frostNoiseAndRoundedHeightFieldsMatchTheWeb() {
        for (fixture in fixtures()) {
            val field = fixture.geometry()
            val texture = field.texture
            assertFloatFields(fixture, "texture.f32le", listOf(texture.noise, texture.clouds, texture.roughX, texture.roughY), 1e-6)
            assertContentEquals(fixture.bytes("alpha.u8"), field.alpha, fixture.id + " alpha")
            assertFloatFields(fixture, "geometry.f32le", listOf(field.profile, field.gradX, field.gradY, field.roundProfile, field.roundGradX, field.roundGradY), 2e-5)
        }
    }

    @Test
    fun opticalDepthAndNormalsMatchTheWeb() {
        for (fixture in fixtures()) {
            val optics = prepareOptics(fixture.geometry(), fixture.settings, fixture.palette)
            assertFloatFields(fixture, "optics.f32le", listOf(optics.normals, optics.colors, optics.dome, optics.shapeY, optics.shapeZ), 5e-5)
        }
    }

    @Test
    fun shadedBodyMatchesAtThreeLightAngles() {
        for (fixture in fixtures()) {
            val field = fixture.geometry()
            for (angle in listOf(0, 180, 315)) {
                val pixels = shadeBody(field, fixture.settings.copy(light = angle.toDouble()), fixture.palette).pixels
                val expected = fixture.bytes("body-$angle.rgba")
                var maximumError = 0
                var different = 0
                for (index in pixels.indices) {
                    assertEquals(expected[index * 4 + 3].toInt() and 255, pixels[index] ushr 24, "${fixture.id} alpha at $index")
                    if (pixels[index] ushr 24 == 0) continue
                    for (channel in 0..2) {
                        val actual = pixels[index] ushr (16 - channel * 8) and 255
                        val reference = expected[index * 4 + channel].toInt() and 255
                        val error = abs(actual - reference)
                        maximumError = max(maximumError, error)
                        if (error != 0) different++
                    }
                }
                assertTrue(maximumError <= 1, "${fixture.id} light=$angle max channel error=$maximumError, different channels=$different")
                assertTrue(different <= pixels.size * 0.01, "${fixture.id} light=$angle more than 1% of channels drifted: $different")
            }
        }
    }

    @Test
    fun completeMaterialStaysCloseToWebRenderIncludingColoredGroundLight() {
        for (fixture in fixtures()) {
            val field = fixture.geometry()
            val ground = fixture.ground(field, fixture.settings)
            val body = shadeBody(field, fixture.settings, fixture.palette)
            val actual = compositeBody(ground, body, fixture.ratio)
            val image = resource("${fixture.id}/material-315.png").use { ImageIO.read(it) }
            assertEquals(image.width, actual.width, fixture.id + " width")
            assertEquals(image.height, actual.height, fixture.id + " height")
            var squaredError = 0.0
            var maxError = 0.0
            for (y in 0 until image.height) for (x in 0 until image.width) {
                val expected = image.getRGB(x, y)
                val native = actual.pixels[y * actual.width + x]
                for (channel in 0..2) {
                    val error = abs(overWhite(expected, channel) - overWhite(native, channel))
                    squaredError += error * error
                    maxError = max(maxError, error)
                }
            }
            val rms = sqrt(squaredError / (image.width * image.height * 3))
            // CSS/Skia blur and Gaussian sampling differ discretely; the body
            // itself has the much stricter raw-channel test above.
            assertTrue(rms < 0.5 && maxError < 6.0, "${fixture.id} full material RMS=$rms, maximum=$maxError")
        }
    }

    @Test
    fun groundShadowDoesNotMoveWithSurfaceLight() {
        for (fixture in fixtures()) {
            val field = fixture.geometry()
            val top = fixture.ground(field, fixture.settings.copy(light = 0.0))
            val bottom = fixture.ground(field, fixture.settings.copy(light = 180.0))
            assertContentEquals(top.pixels, bottom.pixels, fixture.id + " fixed downward ground light")
        }
    }

    private fun fixtures(): List<Fixture> = properties("manifest.properties").getProperty("cases").split(',').map { Fixture(it, properties("$it/case.properties")) }

    private inner class Fixture(val id: String, val properties: Properties) {
        val width = properties.number("width")
        val height = properties.number("height")
        val ratio = properties.number("ratio")
        val shape = when (properties.getProperty("shape")) {
            "disc" -> RenderShape.Disc
            "capsule" -> RenderShape.Capsule
            else -> RenderShape.Rounded
        }
        val settings = RenderSettings(
            frost = properties.number("frost"), grain = properties.number("grain"), tumble = properties.number("tumble"),
            thickness = properties.number("thickness"), bulge = properties.number("bulge"), elevation = properties.number("elevation"),
            light = properties.number("light"), transmission = properties.number("transmission"), seed = properties.getProperty("seed").toLong().toInt(),
        )
        val palette = RenderPalette(properties.getProperty("body").toInt(16), properties.getProperty("edge").toInt(16), properties.getProperty("ink").toInt(16))
        fun bytes(name: String) = resource("$id/$name").use { it.readBytes() }
        fun geometry(): GeometryField {
            val texture = makeTexture(width, height, ratio, settings.seed)
            return makeGeometryField(width, height, shape, settings.tumble, settings.seed, texture, rasterizeMask = { _, w, h, scale, x, y ->
                assertEquals(properties.number("pixelWidth").toInt() + 2, w)
                assertEquals(properties.number("pixelHeight").toInt() + 2, h)
                assertEquals(ratio.coerceAtMost(2.0), scale)
                assertEquals(1.0, x)
                assertEquals(1.0, y)
                bytes("mask.u8")
            })
        }
        fun ground(field: GeometryField, settings: RenderSettings) = renderGroundLayers(width, height, ratio, settings, palette, field.alpha, field.texture.width, field.texture.height)
    }

    private fun resource(path: String) = checkNotNull(javaClass.getResourceAsStream("/reference/$path")) { "Missing reference fixture $path; run npm run --prefix tools generate-reference" }
    private fun properties(path: String) = Properties().apply { resource(path).use { load(it) } }
    private fun Properties.number(key: String) = getProperty(key).toDouble()
    private fun Properties.numbers(key: String) = getProperty(key).split(',').map { it.toDouble() }

    private fun assertNumbers(label: String, expected: List<Double>, actual: List<Double>, tolerance: Double) {
        assertEquals(expected.size, actual.size, "$label length")
        var maximum = 0.0
        var worst = 0
        for (i in actual.indices) {
            val error = abs(expected[i] - actual[i])
            assertTrue(error.isFinite(), "$label nonfinite at $i")
            if (error > maximum) { maximum = error; worst = i }
        }
        assertTrue(maximum <= tolerance, "$label maximum error=$maximum at $worst, expected=${expected[worst]}, actual=${actual[worst]}")
    }

    private fun assertFloatFields(fixture: Fixture, path: String, fields: List<FloatArray>, tolerance: Double) {
        val buffer = ByteBuffer.wrap(fixture.bytes(path)).order(ByteOrder.LITTLE_ENDIAN)
        val expected = List(buffer.remaining() / 4) { buffer.float.toDouble() }
        assertNumbers(fixture.id + " " + path, expected, fields.flatMap { array -> array.map { it.toDouble() } }, tolerance)
    }

    private fun overWhite(argb: Int, channel: Int): Double {
        val alpha = (argb ushr 24) / 255.0
        val value = argb ushr (16 - channel * 8) and 255
        return 255.0 + (value - 255.0) * alpha
    }
}
